refentry.refsect1:
&reftitle.parameters;




   seed


     La graine à définir pour les fonctions gmp_random_bits et
     gmp_random_range.


    &gmp.parameter;

&reftitle.errors;


 Lève une exception ValueError si le
 paramètre seed est invalide.

&reftitle.changelog;





    &Version;
    &Description;





    8.0.0

     Si le paramètre seed est invalide, gmp_random_seed
     lève une exception ValueError dorénavant.
     Précédemment une alerte E_WARNING était émise et &false; était retourné.

  &reftitle.examples;



    Exemple avec gmp_random_seed


<?php
// Définition de la graine
gmp_random_seed(100);

var_dump(gmp_strval(gmp_random_bits(10)));

// Définition de la graine avec une autre valeur
gmp_random_seed(gmp_init(-100));

var_dump(gmp_strval(gmp_random_range(0, 100)));

// Définition de la graine avec une valeur invalide
try {
    gmp_random_seed('not a number');
} catch (\ValueError $e) {
    echo $e->getMessage(), PHP_EOL;
}


    &example.outputs;


string(3) "800"
string(2) "32"
gmp_random_seed(): Argument #1 ($seed) is not an integer string
